    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

wire [5:0] c0 [0:31];
genvar i;
generate
  for (i=0;i<32;i=i+1) begin: L0
    assign c0[i] = a_i[i] ? (i+32) : 6'd0;
  end
endgenerate

wire [5:0] c1 [0:15];
generate
  for (i=0;i<16;i=i+1) begin: L1
    assign c1[i] = (c0[2*i+1] != 6'd0) ? c0[2*i+1] : c0[2*i];
  end
endgenerate

