generate
  for (i=0;i<4;i=i+1) begin: L3
    assign c3[i] = (c2[2*i+1] != 6'd0) ? c2[2*i+1] : c2[2*i];
  end
endgenerate

wire [5:0] c4 [0:1];
generate
  for (i=0;i<2;i=i+1) begin: L4
    assign c4[i] = (c3[2*i+1] != 6'd0) ? c3[2*i+1] : c3[2*i];
  end
endgenerate

wire [5:0] chosen_0 = (c4[1] != 6'd0) ? c4[1] : c4[0];

